import numpy as np
from scipy.optimize import least_squares
d=df.copy()
vac=d[(d.air_density==0)&(d.speed==0)].copy()
vac['g']=2*vac.height/vac.flight_time**2
import statsmodels.formula.api as smf
best=None
for T0 in range(-20,81,5):
  for r0 in [0.3,0.4,0.5,0.6]:
    vac['x']=(vac.reflectance-r0)*(vac.temperature-T0)
    m=smf.ols('g~x',vac).fit()
    if best is None or m.ssr<best[0]: best=(m.ssr,T0,r0,m.params.values)
print(best)
_,T0,r0,(a,b)=best
def G(r,T): return a+b*(r-r0)*(T-T0)
sh={'sphere':0,'cube':1,'cylinder':2}
def sim(row,p):
    k=p[sh[row['shape']]]; g=G(row.reflectance,row.temperature)
    th=np.radians(row.angle); vx=row.speed*np.cos(th); vy=row.speed*np.sin(th); y=row.height;x=0;t=0;dt=0.002
    c=k*row.air_density*row.radius**p[3]/row.mass**p[4]
    while y>0:
        v=np.hypot(vx,vy); vx-=c*v*vx*dt; vy-=(g+c*v*vy)*dt
        x+=vx*dt;y+=vy*dt;t+=dt
    return t,x,np.hypot(vx,vy)
a_=d[d.air_density>0]
sub=a_.sample(60,random_state=1)
def res(p):
    out=[]
    for _,r in sub.iterrows():
        t,x,v=sim(r,p);out+= [(t-r.flight_time)/0.03,(v-r.impact_speed)/(0.01*r.impact_speed+.1)]
        if r.distance>0: out.append((x-r.distance)/(0.02*r.distance))
    return out
f=least_squares(res,[1,1.5,1,2,1],x_scale=[1,1,1,1,1],diff_step=0.05)
print(f.x,np.sum(np.square(f.fun)),len(f.fun))

